#!/usr/bin/env python3
"""install_ai.py - run from the project folder (~/W):  python3 install_ai.py
Makes Sturch ready for an outside AI service, with NO later code changes when you switch services.
  * adds smartrank.py: the only place that talks to the AI (any OpenAI-compatible embeddings API)
  * hooks it into Smart search: the AI only RE-ORDERS real papers from every source (OpenAlex, arXiv, Crossref);
    it never writes text, so nothing is made up
  * adds an "ai" block to /api/smart-status so you can test the connection (never shows the key)
Nothing changes until you set AI_BASE_URL, AI_API_KEY and AI_EMBED_MODEL in Render (see smartrank.py).
Needs install_smart2 first. Safe to run twice."""
import json, os, sys

MOD = '"""smartrank.py - the ONE place where an outside AI service plugs into Sturch.\n\nThe AI is used for RANKING ONLY. It turns your search and each paper\'s title (and abstract) into lists of\nnumbers (embeddings); papers whose numbers are closest to your search move up. It never writes text, so it\ncannot make up answers, and every result is still a real paper from OpenAlex, arXiv or Crossref.\n\nIt works with any OpenAI-compatible embeddings API (OpenAI, Azure OpenAI, and many others).\nSettings, all in Render > Environment (nothing is on until AI_BASE_URL, AI_API_KEY and AI_EMBED_MODEL are set):\n  AI_BASE_URL       e.g. https://api.openai.com/v1      (Sturch calls BASE_URL + /embeddings)\n  AI_API_KEY        the secret key (never put it in code or chat)\n  AI_EMBED_MODEL    e.g. text-embedding-3-small\n  AI_AUTH_HEADER    optional. "api-key" for Azure. Default: Authorization (Bearer)\n  AI_QUERY_PARAMS   optional. e.g. api-version=2024-02-01 (Azure)\n  AI_DAILY_LIMIT    smart searches per day that may use the AI (default 50)\n  AI_POOL           how many top papers are re-ranked (default 30)\n  AI_USE_ABSTRACTS  1 = send title + start of abstract (default), 0 = titles only\nTo use a different AI service later, change these settings only. No code change is needed."""\nimport hashlib\nimport math\nimport os\nimport time\nfrom urllib.parse import urlparse\n\nimport requests\n\n_cache = {}                         # text hash -> vector (saves calls and tokens for repeat papers)\n_day = {"day": None, "n": 0}\n\ndef _env(name, default=""):\n    return (os.environ.get(name, default) or "").strip()\n\ndef available():\n    """True when the AI is set up and today\'s limit is not used up."""\n    if not (_env("AI_BASE_URL") and _env("AI_API_KEY") and _env("AI_EMBED_MODEL")):\n        return False\n    _roll()\n    return _day["n"] < _limit()\n\ndef _limit():\n    try:\n        return int(_env("AI_DAILY_LIMIT", "50"))\n    except ValueError:\n        return 50\n\ndef pool_size():\n    try:\n        return max(5, min(60, int(_env("AI_POOL", "30"))))\n    except ValueError:\n        return 30\n\ndef _roll():\n    today = time.strftime("%Y-%m-%d")\n    if _day["day"] != today:\n        _day["day"], _day["n"] = today, 0\n\ndef paper_text(p):\n    """What is sent to the AI for one paper: the title, plus the start of the abstract unless turned off."""\n    t = (p.get("title") or "").strip()\n    if _env("AI_USE_ABSTRACTS", "1") != "0":\n        a = (p.get("abstract") or "").strip()\n        if a:\n            t += ". " + a[:600]\n    return t[:900]\n\ndef _request(texts, timeout=15):\n    """POST the texts to the embeddings API. Returns (vectors or None, http_status, error_text)."""\n    url = _env("AI_BASE_URL").rstrip("/") + "/embeddings"\n    qp = _env("AI_QUERY_PARAMS")\n    if qp:\n        url += ("&" if "?" in url else "?") + qp\n    header = _env("AI_AUTH_HEADER", "Authorization")\n    key = _env("AI_API_KEY")\n    headers = {"Content-Type": "application/json",\n               header: ("Bearer " + key) if header.lower() == "authorization" else key}\n    try:\n        r = requests.post(url, json={"model": _env("AI_EMBED_MODEL"), "input": texts}, headers=headers, timeout=timeout)\n    except Exception as e:\n        return None, 0, type(e).__name__\n    if not r.ok:\n        try:\n            msg = str(r.json().get("error", r.text))[:200]\n        except Exception:\n            msg = r.text[:200]\n        return None, r.status_code, msg\n    try:\n        data = sorted(r.json()["data"], key=lambda d: d.get("index", 0))\n        vecs = [d["embedding"] for d in data]\n    except Exception:\n        return None, r.status_code, "unexpected answer"\n    if len(vecs) != len(texts):\n        return None, r.status_code, "wrong number of vectors"\n    return vecs, r.status_code, ""\n\ndef _cos(a, b):\n    dot = sum(x * y for x, y in zip(a, b))\n    na = math.sqrt(sum(x * x for x in a)); nb = math.sqrt(sum(y * y for y in b))\n    return dot / (na * nb) if na and nb else 0.0\n\ndef similarities(query, papers):\n    """Closeness (cosine, about 0..1) of each paper to the query, in the same order. None if the AI is off\n    or fails, so the caller falls back to the normal rules. One API call per search at most."""\n    if not papers or not available():\n        return None\n    texts = [paper_text(p) for p in papers]\n    keys = [hashlib.sha1(t.encode("utf-8")).hexdigest() for t in texts]\n    qkey = "q:" + hashlib.sha1(query.encode("utf-8")).hexdigest()\n    need = [i for i, k in enumerate(keys) if k not in _cache]\n    send = ([query] if qkey not in _cache else []) + [texts[i] for i in need]\n    if send:\n        _roll(); _day["n"] += 1\n        vecs, status, err = _request(send)\n        if vecs is None:\n            return None\n        j = 0\n        if qkey not in _cache:\n            _cache[qkey] = vecs[0]; j = 1\n        for i in need:\n            _cache[keys[i]] = vecs[j]; j += 1\n        while len(_cache) > 3000:                      # keep memory small\n            _cache.pop(next(iter(_cache)))\n    qv = _cache[qkey]\n    return [_cos(qv, _cache[k]) for k in keys]\n\ndef diag():\n    """For /api/smart-status. Never includes the key."""\n    out = {"ai_configured": bool(_env("AI_BASE_URL") and _env("AI_API_KEY") and _env("AI_EMBED_MODEL"))}\n    if not out["ai_configured"]:\n        out["note"] = "Set AI_BASE_URL, AI_API_KEY and AI_EMBED_MODEL in Render to turn the AI ranking on."\n        return out\n    _roll()\n    out.update({"host": urlparse(_env("AI_BASE_URL")).netloc, "model": _env("AI_EMBED_MODEL"),\n                "uses_abstracts": _env("AI_USE_ABSTRACTS", "1") != "0",\n                "ai_searches_today": _day["n"], "daily_limit": _limit(), "pool": pool_size()})\n    vecs, status, err = _request(["test"], timeout=10)\n    out["test_http_status"] = status\n    if vecs:\n        out["test_vector_size"] = len(vecs[0])\n    else:\n        out["test_error"] = err\n    return out\n'
SPEC = json.loads('{"search.py": [["import os\\nimport re\\nimport requests\\n", "import os\\nimport re\\nimport requests\\nimport smartrank\\n"], ["        results = _add_smart(results, query, f, sq)\\n", "        results = _add_smart(results, query, f, sq)\\n        results = _ai_rerank(results, query, f)\\n"], ["@search_bp.route(\\"/api/smart-status\\")", "def _ai_rerank(results, query, f):\\n    \\"\\"\\"Optional outside-AI ranking (see smartrank.py). It only re-orders real papers and never writes text.\\n    Off unless the AI settings are set and the person ticked Smart search.\\"\\"\\"\\n    if not f.get(\\"smart\\") or f.get(\\"field\\") == \\"fulltext\\" or not smartrank.available():\\n        return results\\n    pool = results[:smartrank.pool_size()]\\n    sims = smartrank.similarities(query, pool)\\n    if not sims:\\n        if f.get(\\"smart_state\\") in (None, \\"\\", \\"unavailable\\", \\"none\\"):\\n            f[\\"smart_state\\"] = \\"error\\"\\n        return results\\n    lo, hi = min(sims), max(sims)\\n    f[\\"smart_state\\"] = \\"ok\\"\\n    if hi - lo < 1e-6:\\n        return results\\n    for p, s in zip(pool, sims):\\n        share = (s - lo) / (hi - lo)\\n        p[\\"score\\"] = round((p.get(\\"score\\") or 0) + 3 * share, 2)\\n        if share >= 0.5:\\n            p[\\"smart\\"] = True                    # shows the Smart boost badge\\n    if f[\\"sort\\"] == \\"match\\":\\n        results.sort(key=lambda x: (x.get(\\"score\\") or 0, x.get(\\"citations\\") or 0), reverse=True)\\n    return results\\n\\n@search_bp.route(\\"/api/smart-status\\")"], ["    return out\\n\\ndef _add_smart(", "    out[\\"ai\\"] = smartrank.diag()\\n    return out\\n\\ndef _add_smart("]]}')

def find(name):
    for c in (name, os.path.join("routes", name), os.path.join("templates", name)):
        if os.path.isfile(c):
            return c
def read(p): return open(p, encoding="utf-8").read()
def write(p, t): open(p, "w", encoding="utf-8", newline="").write(t)

sp, ep = find("search.py"), find("engine.py")
if not sp or not ep:
    print("search.py / engine.py not found. Run this from the project folder (~/W)."); sys.exit(1)
t = read(sp)
if "_semantic_matches" not in t or "/api/smart-status" not in t:
    print("Run install_smart2.py first (smart search is not installed yet)."); sys.exit(1)
missing = []
for old, new in SPEC["search.py"]:
    if new in t or (new.endswith(old) and new[:-len(old)] in t):
        continue
    if t.count(old) == 1:
        t = t.replace(old, new)
    else:
        missing.append(old[:60].replace("\n", " "))
ok = []
if missing:
    print("warning: search.py left alone, did not match:", " | ".join(missing)); sys.exit(1)
if t != read(sp):
    write(sp + ".new", t); os.replace(sp + ".new", sp); ok.append(sp)
target = os.path.join(os.path.dirname(ep) or ".", "smartrank.py")
if not os.path.isfile(target) or read(target) != MOD:
    write(target, MOD); ok.append(target)
print("Updated:", ", ".join(ok) or "nothing (already done?)")
print("Done. Run git status --short, then commit and push." if ok else "")
